function Status(props){

  const topMessage=""
  const paragraph=""
  if(props.status==="won")
  {
    topMessage="You Win!"
  }
  


  return(
    <div className={props.status}>
        <h2>{topMessage}</h2>
        <p>Well done!🎉</p>
    </div>
  )
}

export default Status
